using System;using System.Collections.Generic;using System.Linq;
internal static class NamedSampleTests
{
 static int checks;static void Check(bool b,string message){checks++;if(!b)throw new Exception(message);}static void Bad(Action a,string message){try{a();}catch(FormatException){checks++;return;}throw new Exception("Expected rejection: "+message);}
 public static int Main(){try{
 var t=new Track{id="one",kind="emitter",start=0,end=10,count=3,speed=1};t.sampleTables=NamedSamples.Parse("delay | clamp | 3, 7, 11\nspeed_sample | wrap | 1.5, 2.5");var c=ExpressionContext.For(t,0);
 foreach(var v in new[]{-100.5,-1,0,.9,1,1.9,2,100,1e40,-1e300,1e300}){double a=RandomExpression.Evaluate("sample.delay("+v.ToString(System.Globalization.CultureInfo.InvariantCulture)+")",0,"x",c);Check(a==NamedSamples.Value(t.sampleTables,"delay",v),"clamp");}
 Check(RandomExpression.Evaluate("sample.speed_sample(-1)",0,"x",c)==2.5,"wrap negative");Check(RandomExpression.Evaluate("sample.speed_sample(2)",0,"x",c)==1.5,"wrap positive");
 Check(RandomExpression.Evaluate("sample.speed_sample(1e300)",0,"x",c)==1.5,"huge wrap positive");Check(RandomExpression.Evaluate("sample.speed_sample(-1e300)",0,"x",c)==1.5,"huge wrap negative");
 t.sampleTables["delay"].mode="error";Bad(()=>RandomExpression.Evaluate("sample.delay(1e300)",0,"x",c),"huge error positive");Bad(()=>RandomExpression.Evaluate("sample.delay(-1e300)",0,"x",c),"huge error negative");Bad(()=>RandomExpression.Evaluate("sample.delay(-0.1)",0,"x",c),"error");Check(RandomExpression.Evaluate("sample.delay(2.9)",0,"x",c)==11,"floor error index");
 Bad(()=>RandomExpression.Evaluate("sample.missing(0)",0,"x",c),"missing");Bad(()=>RandomExpression.Parse("sample.delay()"),"arity0");Bad(()=>RandomExpression.Parse("sample.delay(1,2)"),"arity2");
 Bad(()=>NamedSamples.Parse("bad-name | clamp | 1"),"bad name");Bad(()=>NamedSamples.Parse("delay | nope | 1"),"mode");Bad(()=>NamedSamples.Parse("delay | wrap | NaN"),"finite");Bad(()=>NamedSamples.Parse("delay | clamp | 1\ndelay | clamp | 2"),"duplicate");Bad(()=>NamedSamples.Parse("delay | clamp | "),"empty");
 t.sampleTables["delay"].mode="clamp";string text=NamedSamples.Format(t.sampleTables);Check(NamedSamples.Format(NamedSamples.Parse(text))==text,"CSV roundtrip");var clone=t.Snapshot();clone.sampleTables["delay"].values[0]=99;Check(t.sampleTables["delay"].values[0]==3,"snapshot deep");
 var saved=Json.Read<Track>(Json.Write(t));Check(saved.sampleTables["delay"].values[2]==11,"JSON roundtrip");Check(Json.Read<Track>("{\"id\":\"old\"}").sampleTables.Count==0,"old default");
 var other=new Track{id="other"};other.sampleTables=NamedSamples.Parse("delay | clamp | 100");Check(RandomExpression.Evaluate("sample.delay(0)",0,"x",ExpressionContext.For(other,0))==100,"scope");Check(RandomExpression.Evaluate("sample.delay(0)",0,"x",c)==3,"scope no static contamination");
 for(int seed=0;seed<100;seed++){c.i=seed%3;Check(RandomExpression.Evaluate("sample.delay(i)+random(1)",seed,"stream",c)==RandomExpression.Evaluate("at(i,3,7,11)+random(1)",seed,"stream",c),"RNG parity");}
 t.expressions["speed"]="sample.speed_sample(i)";t.bulletActions.Add(new BulletAction{type="speed",start=1,duration=10,expression="sample.delay(i)"});var state=new EditorState{tracks=new List<Track>{t},duration=10};Motion.Normalize(state);RandomParameters.Attach(state);var world=new BulletWorld(state,new RoomData{width=800,height=608},null);world.Seek(2);var first=world.bullets.Where(b=>!b.dead).Select(b=>b.speed).ToArray();Check(first.Length==3,"actual bullet count");Check(first.SequenceEqual(new double[]{3,7,11}),"age action sample");world.Seek(0);world.Seek(2);Check(world.bullets.Where(b=>!b.dead).Select(b=>b.speed).SequenceEqual(first),"reverse seek");
 var draft=t.Snapshot();draft.sampleTables.Remove("delay");Bad(()=>NamedSamples.Normalize(draft),"ref remove precommit");Check(t.sampleTables.ContainsKey("delay"),"draft isolation");

 var undo=new UndoEntry(new UndoSnapshot{state=state});state.tracks[0].sampleTables["delay"].values[0]=77;var restored=undo.Restore().state;Check(restored.tracks[0].sampleTables["delay"].values[0]==3,"undo restored table");Check(!SceneComparison.Same(state,restored),"scene change notices values");
 int hit=0;var bag1=new NativeProperties();bag1.Add("table","sample",typeof(string),()=>"old",null,null,"",new ParameterActions{EditText=()=>hit=1});var bag2=new NativeProperties();bag2.Add("table","sample",typeof(string),()=>"new",null,null,"",new ParameterActions{EditText=()=>hit=2});Check(bag1.TryRebind(bag2),"table button rebind");((ValueProperty)bag1.GetProperties()[0]).Actions.EditText();Check(hit==2,"table editor points at new selection");
 var template=new Track{id="template",kind="emitter",templateOnly=true,start=0,end=0,count=2,life=20};template.sampleTables=NamedSamples.Parse("velocity | clamp | 2, 4");template.expressions["speed"]="sample.velocity(i)";
 var mother=new Track{id="mother",kind="emitter",start=0,end=0,count=1,life=20};mother.sampleTables=NamedSamples.Parse("velocity | clamp | 99");mother.bulletActions.Add(new BulletAction{type="spawn",start=1,templateId="template",spawnTiming="action-time",inheritAngle=false});
 var families=new EditorState{duration=10,tracks=new List<Track>{mother,template}};Motion.Normalize(families);var familyWorld=new BulletWorld(families,new RoomData{width=800,height=608},null);familyWorld.Seek(2);Check(familyWorld.bullets.Where(b=>b.source.id=="template"&&!b.dead).Select(b=>b.speed).OrderBy(x=>x).SequenceEqual(new double[]{2,4}),"template uses own table not mother");
 var clonedTemplate=template.Snapshot();clonedTemplate.sampleTables["velocity"].values[0]=8;Check(template.sampleTables["velocity"].values[0]==2,"copied template value isolation");
 var missingMode=Json.Read<Track>("{\"id\":\"bad\",\"sampleTables\":{\"delay\":{\"values\":[1]}}}");Bad(()=>NamedSamples.Normalize(missingMode),"explicit mode required");var upper=new Track{id="upper"};upper.expressions["speed"]="SAMPLE.missing(0)";Bad(()=>NamedSamples.Normalize(upper),"uppercase missing reference");

 var staticTrack=new Track{id="static",kind="emitter",start=0,end=10};staticTrack.sampleTables=NamedSamples.Parse("delay | error | 10, 10");staticTrack.expressions["speed"]="sample.delay(0)";staticTrack.keyframes.Add(new Keyframe{property="scale",frame=0,expression="sample.delay(1)"});var staticState=new EditorState{duration=10,tracks=new List<Track>{staticTrack}};Motion.Normalize(staticState);Check(Motion.Value(staticTrack,"speed",0)==10,"initial static base");Check(Motion.Value(staticTrack,"scale",0)==10,"initial key value");int commits=0;
 var stale=staticState.Snapshot();RandomParameters.Attach(stale);stale.tracks[0].sampleTables=NamedSamples.Parse("delay | error | 20, 30");RandomParameters.Attach(stale);Check(Motion.Value(stale.tracks[0],"speed",0)==10,"reproduces Attach-only stale base");Check(Motion.Value(stale.tracks[0],"scale",0)==10,"reproduces Attach-only stale key");
 NamedSamples.ApplyChange(staticState,staticTrack,NamedSamples.Parse("delay | error | 20, 30"),()=>commits++);Check(Motion.Value(staticTrack,"speed",0)==20,"static base changes immediately");Check(Motion.Value(staticTrack,"scale",0)==30,"static key changes immediately");Check(commits==1,"one undo checkpoint");Check(!RandomExpression.IsDynamic("sample.delay(0)"),"lookup remains static");
 string beforeFailure=Json.Write(staticState);Bad(()=>NamedSamples.ApplyChange(staticState,staticTrack,NamedSamples.Parse("delay | error | 999"),()=>commits++),"static key bounds preflight");Check(Json.Write(staticState)==beforeFailure,"failed edit preserves entire state");Check(commits==1,"failed edit does not push undo");
 var frameVariable=new Track{id="sample_variable",kind="variable",start=0,end=0,variableName="local_table_value",variableExpression="sample.value(0)"};frameVariable.sampleTables=NamedSamples.Parse("value | clamp | 12");var consumer=new Track{id="consumer",kind="emitter",start=0,end=1};consumer.expressions["speed"]="global.local_table_value";var variableState=new EditorState{duration=2,tracks=new List<Track>{frameVariable,consumer}};Motion.Normalize(variableState);NamedSamples.ApplyChange(variableState,frameVariable,NamedSamples.Parse("value | clamp | 24"),null);Check(Motion.Value(consumer,"speed",0)==24,"whole-scene owner and variable refresh");
 Console.WriteLine("PASS "+checks+" checks; native UI and GM not run.");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
